const drawer=document.querySelector('#chatDrawer');const backdrop=document.querySelector('#chatBackdrop');const messages=document.querySelector('#messages');const input=document.querySelector('#chatInput');const preview=document.querySelector('#answerPreview');const toast=document.querySelector('#toast');
const answers={family:{match:/family|five|children|kids/i,text:'For a family of five, I would shortlist The Courtyard. Its four bedrooms, garden edge and flexible upstairs lounge offer the most balanced everyday fit.',tag:'RECOMMENDED MATCH',title:'The Courtyard',detail:'4 bedrooms · 2,720 sq ft · private garden',image:'assets/project-02.jpg',source:'Illustrative villa record · 02'},amenities:{match:/amenit|pool|club|fitness|security/i,text:'The concept includes a clubhouse, swimming pool, fitness studio, children’s grove, walking loop and round-the-clock gated security.',tag:'SHARED LIFESTYLE',title:'More than a home',detail:'12+ illustrative shared amenities designed around wellbeing and connection.',image:'assets/about-photo.jpg',source:'Concept amenities schedule'},location:{match:/location|near|school|hospital|city|map/i,text:'The sample location story places daily essentials about 8 minutes away, schools and healthcare within 15 minutes, and the city centre around 25 minutes away.',tag:'LOCATION PREVIEW',title:'Connected, yet calm',detail:'Drive times and map are placeholders pending owner confirmation.',image:'assets/location-map.jpg',source:'Illustrative location map'},visit:{match:/visit|schedule|contact|call|book/i,text:'I can demonstrate a visit-request journey, but this prototype does not send your details. In the live application, an approved sales contact would receive the request.',tag:'DEMO ENQUIRY FLOW',title:'Plan a private visit',detail:'No information is collected or submitted in this concept demonstration.',image:'assets/hero-01.jpg',source:'Prototype interaction only',toast:true},grove:{match:/grove/i,text:'The Grove is the most compact concept: three bedrooms arranged around a private courtyard, with an illustrative built area of 2,180 sq ft.',tag:'VILLA 01 · CONCEPT',title:'The Grove',detail:'3 bedrooms · courtyard living · 2,180 sq ft',image:'assets/project-01.jpg',source:'Illustrative villa record · 01'},courtyard:{match:/courtyard|compare/i,text:'The Courtyard adds a fourth bedroom and larger garden setting compared with The Grove, while remaining more compact than the signature Canopy home.',tag:'VILLA 02 · CONCEPT',title:'The Courtyard',detail:'4 bedrooms · garden edge · 2,720 sq ft',image:'assets/project-02.jpg',source:'Illustrative villa comparison'},canopy:{match:/canopy/i,text:'The Canopy is the largest illustrative home, with four bedrooms, generous shared spaces and a built area of about 3,150 sq ft.',tag:'VILLA 03 · CONCEPT',title:'The Canopy',detail:'4 bedrooms · signature plan · 3,150 sq ft',image:'assets/project-03.jpg',source:'Illustrative villa record · 03'},default:{text:'This concept assistant currently knows about villa options, family suitability, amenities, location and visit requests. Try asking one of those questions.',tag:'DEMO ASSISTANT',title:'Let’s explore together',detail:'Choose a topic to see a matching visual summary and reference.',image:'assets/hero-02.jpg',source:'Concept presentation'}};
function openChat(question){drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');backdrop.hidden=false;document.body.style.overflow='hidden';setTimeout(()=>input.focus(),350);if(question)setTimeout(()=>respond(question),200)}function closeChat(){drawer.classList.remove('open');drawer.setAttribute('aria-hidden','true');backdrop.hidden=true;document.body.style.overflow=''}function selectAnswer(q){return Object.values(answers).find(a=>a.match&&a.match.test(q))||answers.default}function respond(q){if(!q.trim())return;messages.insertAdjacentHTML('beforeend',`<div class="message user"><p>${escapeHtml(q)}</p></div>`);const a=selectAnswer(q);setTimeout(()=>{messages.insertAdjacentHTML('beforeend',`<div class="message assistant"><span>GP</span><p>${a.text}</p></div>`);messages.scrollTop=messages.scrollHeight;preview.innerHTML=`<div class="preview-image" style="background-image:url('${a.image}')"><span>LIVE PREVIEW</span></div><div class="preview-content"><small>${a.tag}</small><h3>${a.title}</h3><p>${a.detail}</p><div class="preview-source">Reference · ${a.source}</div></div>`;if(a.toast){toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2800)}},420)}function escapeHtml(s){const d=document.createElement('div');d.textContent=s;return d.innerHTML}document.querySelectorAll('[data-open-chat]').forEach(b=>b.addEventListener('click',()=>openChat()));document.querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>openChat(b.dataset.question)));document.querySelectorAll('#suggestions button').forEach(b=>b.addEventListener('click',()=>respond(b.textContent)));document.querySelector('#closeChat').addEventListener('click',closeChat);backdrop.addEventListener('click',closeChat);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeChat()});document.querySelector('#chatForm').addEventListener('submit',e=>{e.preventDefault();const q=input.value;input.value='';respond(q)});
